/** Closes the period, fixing its due-total (see {@link PeriodCloser}). A closed period cannot be
 *  closed again; a soft-closed one can, fixing its figures afresh. Only the roles the permission matrix allows may close it (clerk and steward by
 *  default). Publishes the closed period. */
public class ClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, Settings settings, PeriodCloser closer,
            Out<ClosedPeriod> closed) throws PeriodClosedException {
        if (!settings.allows(period.sheetId(), "close", request.user())) {
            throw new PeriodClosedException("Your role may not close period " + period.name());
        }
        if (period.hardClosed()) throw new PeriodClosedException("Period " + period.name() + " is already closed");
        closed.set(new ClosedPeriod(closer.close(period)));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Soft-closes the period, fixing its due-total and each person's (see {@link PeriodCloser}) while
 *  claims dated in it can still be changed. Only an open period can be soft-closed, and only by the
 *  roles the permission matrix allows to close it. Publishes the soft-closed period. */
public class SoftClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, Settings settings, PeriodCloser closer,
            Out<ClosedPeriod> closed) throws PeriodClosedException {
        if (!settings.allows(period.sheetId(), "close", request.user())) {
            throw new PeriodClosedException("Your role may not close period " + period.name());
        }
        if (period.closed()) throw new PeriodClosedException("Period " + period.name() + " is already closed");
        closed.set(new ClosedPeriod(closer.close(period, true)));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Reopens a closed period, making its due-total live again. Only the roles the permission matrix allows may reopen a period (a steward by default),
 *  and only a closed one, not locked, can be reopened. Publishes the reopened period. */
public class ReopenPeriod {
    public void reopen(@Val Period period, @Val PeriodCloseRequest request, Periods periods, Settings settings,
            Out<ReopenedPeriod> reopened) throws PeriodClosedException {
        if (!settings.allows(period.sheetId(), "reopen", request.user())) {
            throw new PeriodClosedException("Your role may not reopen period " + period.name());
        }
        if (period.locked()) throw new PeriodClosedException("Period " + period.name() + " is locked");
        if (!period.closed()) throw new PeriodClosedException("Period " + period.name() + " is not closed");
        periods.reopen(period);
        reopened.set(new ReopenedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to(), period.cap())));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Runs once the sheet's new today is set: while the sheet has grace days, every open period (not a soft-closed
 *  one: its figures stay as fixed) whose to-date plus them is before the new today is closed, in order of their to-dates, exactly as a
 *  close by hand would, each writing its PERIOD_CLOSED line ending auto=yes. */
public class AutoClosePeriods {
    public void close(@PathVariable("sheetId") String sheetId, @Val LocalDate today, @Val Actor actor,
            Settings settings, Periods periods, PeriodCloser closer, Audit audit) {
        Integer grace = settings.graceDays(sheetId);
        if (grace == null) return;
        List<Period> due = periods.onSheet(sheetId).stream()
                .filter(p -> !p.closed() && p.to().plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to))
                .toList();
        for (Period open : due) {
            Period period = closer.close(periods.find(sheetId, open.name()));
            audit.record("PERIOD_CLOSED sheet=" + sheetId + " by=" + actor.user() + " period=" + period.name()
                    + " total=" + period.closedTotal().setScale(2).toPlainString() + " auto=yes");
        }
    }
}
